import{_ as s,a0 as l,w as u,s as d,I as t,x as p,a1 as r,A as a,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"在 CentOS 和 RHEL 上安裝 Puppet 服務器和客户端 | LCTT x X-CMD","titleTemplate":false,"description":"在 CentOS 和 RHEL 上安裝 Puppet 服務器和客户端 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 CentOS 和 RHEL 上安裝 Puppet 服務器和客户端 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 CentOS 和 RHEL 上安裝 Puppet 服務器和客户端 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140808 How to install Puppet server and client on CentOS and RHEL","title":"在 CentOS 和 RHEL 上安裝 Puppet 服務器和客户端","tag":"201410","desc":""},"relativePath":"201410/20140808 How to install Puppet server and client on CentOS and RHEL.md","filePath":"[post].md"}'),i={name:"201410/20140808 How to install Puppet server and client on CentOS and RHEL.md"};function m(c,e,P,h,f,b){const o=l("Link");return u(),d("div",null,[e[22]||(e[22]=t("h1",{id:"在-centos-和-rhel-上安裝-puppet-服務器和客户端",tabindex:"-1"},[p("在 CentOS 和 RHEL 上安裝 Puppet 服務器和客户端 "),t("a",{class:"header-anchor",href:"#在-centos-和-rhel-上安裝-puppet-服務器和客户端","aria-label":"Permalink to “在 CentOS 和 RHEL 上安裝 Puppet 服務器和客户端”"},"​")],-1)),e[23]||(e[23]=t("p",null,"當手中有相當多的機器需要管理的時候，自動化處理冗餘又無聊的任務對系統管理員來説就很重要了。很多管理員習慣了自己寫腳本模擬複雜軟件之間的調度。不幸的是，腳本會過時，腳本的作者會離職，如果不花費巨大精力來維護這些腳本的話，它們早晚會一點兒用也沒有。如果能有一個系統，任何人都可以使用、安裝工具，不論其受僱於何人，那真是太期待了。目前已有幾種系統可以解決這類需求，這篇教程將介紹其中之一——Puppet——的使用方法。",-1)),e[24]||(e[24]=t("h3",{id:"puppet-是什麼",tabindex:"-1"},[p("Puppet 是什麼？ "),t("a",{class:"header-anchor",href:"#puppet-是什麼","aria-label":"Permalink to “Puppet 是什麼？”"},"​")],-1)),t("p",null,[e[1]||(e[1]=p("Puppet 是一款為 IT 系統管理員和顧問們設計的自動化軟件，你可以用它自動化地完成諸如安裝應用程序和服務、補丁管理和部署等工作。所有資源的相關配置都以“manifests”的方式保存，單台機器或者多台機器都可以使用。如果你想了解更多內容，Puppet 實驗室的網站上有關於 ",-1)),r(o,{href:"https://puppetlabs.com/puppet/what-is-puppet/"},{default:a(()=>[...e[0]||(e[0]=[p("Puppet 及其工作原理",-1)])]),_:1}),e[2]||(e[2]=p("的更詳細的介紹。",-1))]),e[25]||(e[25]=n(`<h3 id="本教程要做些什麼" tabindex="-1">本教程要做些什麼？ <a class="header-anchor" href="#本教程要做些什麼" aria-label="Permalink to “本教程要做些什麼？”">​</a></h3><p>在這篇教程裏，我們將一起安裝配置一個 Puppet 服務器，然後在我們的客户端服務器（譯註：這裏的“客户端服務器”指需要部署業務邏輯的服務器）上完成一些基本配置。</p><h3 id="準備工作" tabindex="-1">準備工作 <a class="header-anchor" href="#準備工作" aria-label="Permalink to “準備工作”">​</a></h3><p>由於 Puppet 不是 CentOS 或 RHEL 發行版的基本倉庫，所以我們得手動添加 Puppet 實驗室提供的自定義倉庫。在所有你想使用 Puppet 的地方執行以下命令安裝這個倉庫（版本不同，對應的 RPM 文件名可能略有不同）。</p><p><strong>對於 CentOS/RHEL 6.5:</strong></p><pre><code># rpm -ivh https://yum.puppetlabs.com/el/6.5/products/x86_64/puppetlabs-release-6-10.noarch.rpm
</code></pre><p><strong>對於 CentOS/RHEL 7:</strong></p><pre><code> # rpm -ivh https://yum.puppetlabs.com/el/7/products/x86_64/puppetlabs-release-7-10.noarch.rpm
</code></pre><h3 id="安裝服務器端" tabindex="-1">安裝服務器端 <a class="header-anchor" href="#安裝服務器端" aria-label="Permalink to “安裝服務器端”">​</a></h3><p>在你打算用作 master 的服務器上安裝 &quot;puppet-server&quot; 包。</p><pre><code># yum install puppet-server
</code></pre><p>安裝完成後，設置 Puppet 服務器開機自動啓動，然後啓動它。</p><pre><code># chkconfig puppetmaster on
# service puppetmaster start
</code></pre><p>現在服務器已經運行起來了，我們試試看我們的網絡能不能訪問到它。</p><p>對於使用 iptables 當做防火牆的 CentOS/RHEL 6，在 <code>/etc/sysconfig/iptables</code> 文件的 <code>OUTPUT ACCEPT</code> 小節裏添加下面這一行。</p><blockquote><p>-A INPUT -m state --state NEW -m tcp -p tcp --dport 8140 -j ACCEPT</p></blockquote><p>重新啓動 iptables 服務讓剛才的修改生效。</p><pre><code># service iptables restart
</code></pre><p>在安裝了防火牆的 CentOS/RHEL 7 上，我們這麼做：</p><pre><code># firewall-cmd --permanent --zone=public --add-port=8140/tcp
# firewall-cmd --reload
</code></pre><h3 id="安裝客户端" tabindex="-1">安裝客户端 <a class="header-anchor" href="#安裝客户端" aria-label="Permalink to “安裝客户端”">​</a></h3><p>執行下面的命令，在客户端節點安裝 Puppet 客户端。</p><pre><code># yum install puppet
</code></pre><p>安裝完成後，確保 Puppet 會隨開機自動啓動。</p><pre><code># chkconfig puppet on
</code></pre><p>Puppet 客户端需要知道 Puppet master 服務器的地址。最佳方案是使用 DNS 服務器解析 Puppet master 服務器地址。如果你沒有 DNS 服務器，在 <code>/etc/hosts</code> 裏添加類似下面這幾行也可以：</p><blockquote><p>1.2.3.4 server.your.domain</p></blockquote><blockquote><p>2.3.4.5 client-node.your.domain</p></blockquote><p>1.2.3.4 對應你的 Puppet master 服務器 IP 地址，“server.your.domain”是你的 master 服務器域名（默認通常是服務器的 hostname），“client-node.your.domain”是你的客户端節點。包括 Puppet master 和客户端，所有相關的服務器都要在 hosts 文件裏配置。</p><p>完成這些設置之後，我們要讓 Puppet 客户端知道它的 master 是誰。默認情況下，Puppet 會查找名為“puppet”的服務器，但通常這並不符合你網絡環境的真實情況，所以我們要改成 Pupper master 服務器的完整域名。打開文件 <code>/etc/sysconfig/puppet</code>，把 <code>PUPPET_SERVER</code> 變量的值改成你在 <code>/etc/hosts</code> 文件裏指定的 Puppet master 服務器的域名。</p><blockquote><p>PUPPET_SERVER=server.your.domain</p></blockquote><p>master 服務器名也要在 <code>/etc/puppet/puppet.conf</code> 文件的“[agent]”小節裏事先定義好。</p><blockquote><p>server=server.your.domain</p></blockquote><p>現在可以啓動 Puppet 客户端了：</p><pre><code># service puppet start
</code></pre><p>強制我們的客户端在 Puppet master 服務器上登記：</p><pre><code># puppet agent --test
</code></pre><p>你會看到類似於下面的輸出。別怕，這是正常現象，因為服務器還沒有在 Puppet master 服務器上驗證過。</p><blockquote><p>Exiting; no certificate found and waitforcert is disabled</p></blockquote><p>返回 Puppet master 服務器，檢查證書驗證請求：</p><pre><code># puppet cert list
</code></pre><p>你應該能看到一個列出了所有向 Puppet master 服務器發起證書籤名請求的服務器。找到你客户端服務器的 hostname 然後使用下面的命令簽名（client-node 是你客户端節點的域名）：</p><pre><code># puppet cert sign client-node
</code></pre><p>到此為止 Puppet 客户端和服務器都正常工作了。恭喜你！但是，現在 Puppet master 沒有任何要客户端做的事兒。好吧，我們來創建一些基本的 manifest 文件然後讓我們的客户端節點安裝一些基本工具。</p><p>回到你的 Puppet 服務器，確保目錄 <code>/etc/puppet/manifests</code> 存在。</p><pre><code># mkdir -p /etc/puppet/manifests
</code></pre><p>創建 manifest 文件 <code>/etc/puppet/manifests/site.pp</code>，內容如下</p><pre><code>node &#39;client-node&#39; {
        include custom_utils
}

class custom_utils {
        package { [&quot;nmap&quot;,&quot;telnet&quot;,&quot;vim-enhanced&quot;,&quot;traceroute&quot;]:
                ensure =&gt; latest,
                allow_virtual =&gt; false,
        }
}
</code></pre><p>然後重新啓動 puppetmaster 服務。</p><pre><code># service puppetmaster restart
</code></pre><p>客户端默認每 30 分鐘更新一次配置，如果你希望你的修改能強制生效，就在客户端執行如下命令：</p><pre><code># puppet agent -t
</code></pre><p>如果你需要修改客户端的默認刷新時間，編輯客户端節點的 <code>/etc/puppet/puppet.conf</code> 文件中“[agent]”小節，增加下面這一行：</p><blockquote><p><code>runinterval = &lt;yourtime&gt;</code></p></blockquote><p>這個選項的值可以是秒（格式比如 30 或者 30s），分鐘（30m），小時（6h），天（2d）以及年（5y）。值得注意的是，<strong>0 意味着“立即執行”而不是“從不執行”</strong>。</p><h3 id="提示和技巧" tabindex="-1">提示和技巧 <a class="header-anchor" href="#提示和技巧" aria-label="Permalink to “提示和技巧”">​</a></h3><h4 id="_1-調試" tabindex="-1">1. 調試 <a class="header-anchor" href="#_1-調試" aria-label="Permalink to “1. 調試”">​</a></h4><p>你免不了會提交錯誤的配置，然後不得不通過調試判斷問題出現在哪兒。一般來説，你要麼通過查看日誌文件 <code>/var/log/puppet</code> 着手解決問題，要麼手動執行查看輸出：</p><pre><code># puppet agent -t
</code></pre><p>使用“-t”選項，你可以看到 Puppet 的詳細輸出。這條命令還有額外的選項可以幫你定位問題。首先要介紹的選項是：</p><pre><code># puppet agent -t --debug
</code></pre><p>debug 選項會顯示 Puppet 本次運行時的差不多每一個步驟，這在調試非常複雜的問題時很有用。另一個很有用的選項是：</p><pre><code># puppet agent -t --noop
</code></pre><p>這個選項讓 puppet 工作在 dry-run（譯註：空轉模式，不會對真實環境產生影響）模式下，不會應用任何修改。Puppet 只會把其工作內容輸出到屏幕上，不會寫到磁盤裏去。</p><h4 id="_2-模組" tabindex="-1">2. 模組 <a class="header-anchor" href="#_2-模組" aria-label="Permalink to “2. 模組”">​</a></h4>`,65)),t("p",null,[e[4]||(e[4]=p("有時候你需要更復雜的 manifest 文件，在你着手編寫它們之前，你有必要花點兒時間瀏覽一下 ",-1)),r(o,{href:"https://forge.puppetlabs.com/"},{default:a(()=>[...e[3]||(e[3]=[p("https://forge.puppetlabs.com",-1)])]),_:1}),e[5]||(e[5]=p("。Forge 是一個集合了 Puppet 模組的社區，你的問題很可能已經有人解答過了，你能在那兒找到解決問題的模組。如果找不到，那就自己寫一個然後提交上去，其他人也能從中獲益。",-1))]),e[26]||(e[26]=n(`<p>現在，假設你已經找到了一個模組能解決你的問題。怎麼把它安裝到你的系統中去呢？非常簡單，因為 Puppet 已經有了可以直接下載模組的用户界面，只需要執行下面的命令：</p><pre><code># puppet module install &lt;module_name&gt; --version 0.0.0
</code></pre><p><code>&lt;module_name&gt;</code> 是你選擇的模組的名字，版本號可選（如果沒有指定版本號，默認使用最新的版本）。如果你不記得想安裝的模組的名字了，試試下面的命令搜索模組：</p><pre><code># puppet module search &lt;search_string&gt;
</code></pre><p>你會得到一個包含 search_string 的列表。</p><pre><code># puppet module search apache
</code></pre><hr><pre><code>Notice: Searching https://forgeapi.puppetlabs.com ...
NAME                               DESCRIPTION                                                                                         AUTHOR          KEYWORDS
example42-apache                   Puppet module for apache                                                                            @example42      example42, apache
puppetlabs-apache                  Puppet module for Apache                                                                            @puppetlabs     apache web httpd centos rhel ssl wsgi proxy
theforeman-apache                  Apache HTTP server configuration                                                                    @theforeman     foreman apache httpd DEPRECATED
</code></pre><p>如果你想查看已經安裝了哪些模組，鍵入：</p><pre><code># puppet module list
</code></pre><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>到目前為止，你應該有了功能完整的可以向一個或多個客户端服務器推送基本配置的 Puppet master 服務器。你可以自己隨便加點兒配置適配你自己的網絡環境。不必為試用 Puppet 擔心，你會發現，它會拯救你的生活。</p>`,12)),t("p",null,[e[7]||(e[7]=p("Puppet 實驗室正在試着維護一個質量上乘的項目文檔，所以如果你想學點兒關於 Puppet 相關的配置，我強烈推薦你訪問 Puppet 項目的主頁 ",-1)),r(o,{href:"http://docs.puppetlabs.com/"},{default:a(()=>[...e[6]||(e[6]=[p("http://docs.puppetlabs.com",-1)])]),_:1}),e[8]||(e[8]=p("。",-1))]),e[27]||(e[27]=t("p",null,"如果你有任何問題，敬請在文章下方評論，我會盡我所能回答你並給你建議。",-1)),e[28]||(e[28]=t("hr",null,null,-1)),t("p",null,[e[10]||(e[10]=p("via: ",-1)),r(o,{href:"http://xmodulo.com/2014/08/install-puppet-server-client-centos-rhel.html"},{default:a(()=>[...e[9]||(e[9]=[p("http://xmodulo.com/2014/08/install-puppet-server-client-centos-rhel.html",-1)])]),_:1})]),t("p",null,[e[14]||(e[14]=p("作者：",-1)),r(o,{href:"http://xmodulo.com/author/jaroslav"},{default:a(()=>[...e[11]||(e[11]=[p("Jaroslav Štěpánek",-1)])]),_:1}),e[15]||(e[15]=p(" 譯者：",-1)),r(o,{href:"https://github.com/sailing"},{default:a(()=>[...e[12]||(e[12]=[p("sailing",-1)])]),_:1}),e[16]||(e[16]=p(" 校對：",-1)),r(o,{href:"https://github.com/wxy"},{default:a(()=>[...e[13]||(e[13]=[p("wxy",-1)])]),_:1})]),t("p",null,[e[19]||(e[19]=p("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[17]||(e[17]=[p("LCTT",-1)])]),_:1}),e[20]||(e[20]=p(" 原創翻譯，",-1)),r(o,{href:"http://linux.cn/"},{default:a(()=>[...e[18]||(e[18]=[p("Linux中國",-1)])]),_:1}),e[21]||(e[21]=p(" 榮譽推出",-1))])])}const E=s(i,[["render",m]]);export{C as __pageData,E as default};
